// Fotky vložené přímo do skriptu, takže nepotřebuješ žádnou složku s obrázky.
(() => {
  const photos = {
    oktavka: "data:image/jpeg;base64,",
    wolt: "data:image/jpeg;base64,"
  };
  document.querySelectorAll('img[data-photo]').forEach(img => {
    const src = photos[img.dataset.photo];
    if (src) img.src = src;
  });
})();
